# Policy that only allows reading one bucket, nothing more
{
  "Effect": "Allow",
  "Action": ["s3:GetObject", "s3:ListBucket"],
  "Resource": ["arn:aws:s3:::app-logs", "arn:aws:s3:::app-logs/*"]
}

{
  "Version": "2012-10-17",
  "Statement": [{
    "Effect": "Deny",        # Allow or Deny
    "Action": "s3:DeleteBucket",
    "Resource": "*"
  }]
}

# Bucket policy granting another account read access
{"Version": "2012-10-17", "Statement": [{
  "Effect": "Allow",
  "Principal": {"AWS": "arn:aws:iam::210987654321:role/Reader"},
  "Action": "s3:GetObject",
  "Resource": "arn:aws:s3:::shared-data/*"}]}

# handler.py
def handler(event, context):
    return {"statusCode": 200, "body": f"got {len(event.get('Records', []))} records"}

aws lambda create-function --function-name hello --runtime python3.12 \
  --handler handler.handler --zip-file fileb://fn.zip --role arn:aws:iam::123456789012:role/lambda-exec

# Terraform: an S3 bucket as the origin behind a distribution
resource "aws_cloudfront_distribution" "site" {
  origin {
    domain_name = aws_s3_bucket.site.bucket_regional_domain_name
    origin_id   = "s3-site"
  }
  default_cache_behavior { target_origin_id = "s3-site" ... }
}
